bb\":2623,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/10/18/\",\"title\":\"TEXT 18\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/10/20/\",\"title\":\"TEXT 20\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":2963,\"bb\":568258,\"url_path\":\"/en/library/bg/10/19/devanagari/\",\"body_final\":\"श्रीभगवानुवाच
हन्त ते कथयिष्यामि दिव्या ह्यात्मविभूतय: ।
प्राधान्यत: कुरुश्रेष्ठ नास्त्यन्तो विस्तरस्य मे ॥ १९ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2964,\"bb\":2624,\"url_path\":\"/en/library/bg/10/19/b2624/\",\"body_value\":\"śrī-bhagavān uvāca
hanta te kathayiṣyāmi
divyā hy ātma-vibhūtayaḥ
prādhānyataḥ kuru-śreṣṭha
nāsty anto vistarasya me\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":2965,\"bb\":2625,\"url_path\":\"/en/library/bg/10/19/b2625/\",\"shadow_value\":\"śrī-bhagavān uvāca – the Supreme Personality of Godhead said; hanta – yes; te – unto you; kathayiṣyāmi – I shall speak; divyāḥ – divine; hi – certainly; ātma-vibhūtayaḥ – personal opulences; prādhānyataḥ – which are principal; kuru-śreṣṭha – O best of the Kurus; na asti – there is not; antaḥ – limit; vistarasya – to the extent; me – My.\",\"word_for_word_value\":[{\"word\":\"śrī-bhagavān uvāca\",\"translation\":\"the Supreme Personality of Godhead said\"},{\"word\":\"hanta\",\"translation\":\"yes\"},{\"word\":\"te\",\"translation\":\"unto you\"},{\"word\":\"kathayiṣyāmi\",\"translation\":\"I shall speak\"},{\"word\":\"divyāḥ\",\"translation\":\"divine\"},{\"word\":\"hi\",\"translation\":\"certainly\"},{\"word\":\"ātma-vibhūtayaḥ\",\"translation\":\"personal opulences\"},{\"word\":\"prādhānyataḥ\",\"translation\":\"which are principal\"},{\"word\":\"kuru-śreṣṭha\",\"translation\":\"O best of the Kurus\"},{\"word\":\"na asti\",\"translation\":\"there is not\"},{\"word\":\"antaḥ\",\"translation\":\"limit\"},{\"word\":\"vistarasya\",\"translation\":\"to the extent\"},{\"word\":\"me\",\"translation\":\"My\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":2966,\"bb\":2626,\"url_path\":\"/en/library/bg/10/19/b2626/\",\"body_value\":\"The Supreme Personality of Godhead said: Yes, I will tell you of My splendorous manifestations, but only of those which are prominent, O Arjuna, for My opulence is limitless.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2967,\"bb\":2627,\"url_path\":\"/en/library/bg/10/19/b2627/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2968,\"bb\":2628,\"url_path\":\"/en/library/bg/10/19/b2628/\",\"body_value\":\"The impersonalist or pantheist cannot understand the exceptional opulences of the Supreme Lord nor the manifestations of His divine energies. Both in the material world and in the spiritual world His energies are distributed in every variety of manifestation. Now Kṛṣṇa is describing what can be directly perceived by the common man; thus part of His variegated energy is described in this way.\"}]}],\"short_title\":\"Bg. 10.19\",\"medium_title\":\"Bhagavad-gītā As It Is 10.19\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n26:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/\",\"className\":\"text-vb-link\",\"children\":\"Library\"}],\" » \"