anced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/10/21/\",\"title\":\"TEXT 21\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":2970,\"bb\":568259,\"url_path\":\"/en/library/bg/10/20/devanagari/\",\"body_final\":\"अहमात्मा गुडाकेश सर्वभूताशयस्थित: ।
अहमादिश्च मध्यं च भूतानामन्त एव च ॥ २० ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2971,\"bb\":2630,\"url_path\":\"/en/library/bg/10/20/b2630/\",\"body_value\":\"aham ātmā guḍākeśa
sarva-bhūtāśaya-sthitaḥ
aham ādiś ca madhyaṁ ca
bhūtānām anta eva ca\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":2972,\"bb\":2631,\"url_path\":\"/en/library/bg/10/20/b2631/\",\"shadow_value\":\"aham – I; ātmā – the soul; guḍākeśa – O Arjuna; sarva-bhūta – of all living entities; āśaya-sthitaḥ – situated within the heart; aham – I am; ādiḥ – the origin; ca – also; madhyam – middle; ca – also; bhūtānām – of all living entities; antaḥ – end; eva – certainly; ca – and.\",\"word_for_word_value\":[{\"word\":\"aham\",\"translation\":\"I\"},{\"word\":\"ātmā\",\"translation\":\"the soul\"},{\"word\":\"guḍākeśa\",\"translation\":\"O Arjuna\"},{\"word\":\"sarva-bhūta\",\"translation\":\"of all living entities\"},{\"word\":\"āśaya-sthitaḥ\",\"translation\":\"situated within the heart\"},{\"word\":\"aham\",\"translation\":\"I am\"},{\"word\":\"ādiḥ\",\"translation\":\"the origin\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"madhyam\",\"translation\":\"middle\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"bhūtānām\",\"translation\":\"of all living entities\"},{\"word\":\"antaḥ\",\"translation\":\"end\"},{\"word\":\"eva\",\"translation\":\"certainly\"},{\"word\":\"ca\",\"translation\":\"and\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":2973,\"bb\":2632,\"url_path\":\"/en/library/bg/10/20/b2632/\",\"body_value\":\"I am the Supersoul, O Arjuna, seated in the hearts of all living entities. I am the beginning, the middle and the end of all beings.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2974,\"bb\":2633,\"url_path\":\"/en/library/bg/10/20/b2633/\",\"body_value\":\"In this verse Arjuna is addressed as Guḍākeśa, which means “one who has conquered the darkness of sleep.” For those who are sleeping in the darkness of ignorance, it is not possible to understand how the Supreme Personality of Godhead manifests Himself in various ways in the material and spiritual worlds. Thus this address by Kṛṣṇa to Arjuna is significant. Because Arjuna is above such darkness, the Personality of Godhead agrees to describe His various opulences.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2975,\"bb\":2634,\"url_path\":\"/en/library/bg/10/20/b2634/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2976,\"bb\":2635,\"url_path\":\"/en/library/bg/10/20/b2635/\",\"body_value\":\"The three puruṣa-avatāras are described in Śrīmad-Bhāgavatam. They are also described in the Nārada Pañcarātra, one of the Sātvata-tantras. Viṣṇos tu trīṇi rūpāṇi puruṣākhyāny atho viduḥ: the Supreme Personality of Godhead manifests three features – as Kāraṇodaka-śāyī Viṣṇu, Garbhodaka-śāyī Viṣṇu and Kṣīrodaka-śāyī Viṣṇu – in this material manifestation. The Mahā-viṣṇu, or Kāraṇodaka-śāyī Viṣṇu, is described in the Brahma-saṁhitā (5.47). Yaḥ kāraṇārṇava-jale bhajati sma yoga-nidrām: the Supreme Lord, Kṛṣṇa, the cause of all causes, lies down in the cosmic ocean as Mahā-viṣṇu. Therefore the Supreme Personality of Godhead is the beginning of this universe, the maintainer of the universal manifestations, and the end of all energy.\"}]}],\"short_title\":\"Bg. 10.20\",\"medium_title\":\"Bhagavad-gītā As It Is 10.20\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/